// SetRefreshInterval changes the per-feed polling interval (in minutes).
// When a shorter interval is set, the next check is brought forward so the
// new interval takes effect without waiting for the previously scheduled check.
// @effects: mut
func (f *Feed) SetRefreshInterval(minutes int) {
	if minutes == f.RefreshInterval {
		return
	}

	f.RefreshInterval = minutes
	if minutes > 0 {
		nextCheckAt := time.Now().Add(time.Duration(minutes) * time.Minute)
		if f.NextCheckAt.After(nextCheckAt) {
			f.NextCheckAt = nextCheckAt
		}
	}
}

